"""
kb_backlinks.py — 链接图分析与补链建议

用途：
  · 找出「孤立页面」（无入站链接）与「弱连接页面」
  · 为孤立页面推荐最该链接到它的页面（基于内容相似度）
  · 输出可直接执行的补链清单

用法：
  python tools/kb_backlinks.py              # 概览：链接图统计 + 孤立页面 TOP
  python tools/kb_backlinks.py --suggest    # 为孤立页面生成补链建议
  python tools/kb_backlinks.py --suggest --type concept   # 只处理某类页面
  python tools/kb_backlinks.py --page 固态电解质          # 查某页的入站/出站链接
"""

import os
