sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import kb_lib as K


def load_full():
    if not os.path.exists(K.FULL_PATH):
        sys.stderr.write("[!] 缺少 meta_full.json，请先运行 kb_build_index.py\n")
        sys.exit(2)
    with open(K.FULL_PATH, "r", encoding="utf-8") as f:
        return json.load(f)["pages"]


def norm_target(t):
    """把 wikilink 目标归一成页面名（去目录前缀）。

    需处理表格里的转义分隔符 \\|（Obsidian 表格内写法）。
    ⚠️ 页面链接（`sources/Foo.md`）须剥 `.md` 才与页面名键对齐——本库大量页面
       在 `sources:` 字段用 `[[sources/Foo.md]]` 显式带扩展名；不剥则这些入站
       引用**全部漏计**（2026-10-10 实测漏计 523 条 / 1170 个带 .md 的目标）。
       仅对**非 raw/ 资源**生效（raw 资源取末段后 `.md` 是其真实文件名，须保留）。
    """
    is_raw = t.strip().startswith("raw/")
    t = t.replace("\\|", "|").split("|")[0].split("#")[0].strip()
    t = t.replace("\\", "").split("/")[-1]
    if not is_raw and t.endswith(".md"):
        t = t[:-3]
    return t


def build_graph(pages):
    """返回 (inbound, outbound)。键为页面名。"""
    names = set(pages)
    inbound = defaultdict(set)
    outbound = defaultdict(set)
    for name, m in pages.items():
        for t in m.get("out", []):
            tgt = norm_target(t)
            if tgt in names and tgt != name:
                inbound[tgt].add(name)
                outbound[name].add(tgt)
    return inbound, outbound


def tokens_from_bm(bm):
    """从 BM25 索引还原 {页面名: [token, ...]}。

    2026-10-09 修：索引已从 v1（正排 `_tokens`）迁移到 v2（倒排 `postings`），
    而本脚本一直读 `bm["_tokens"]` ⇒ 默认 / --page / --suggest **三种模式全部
    KeyError 崩掉**，只有不碰 bm25 的 --selftest 还绿。结果是库里"入站≥1、出站≥2"
    的补链纪律长期没有工具支撑（`kb_toolcheck.py` 只跑 --selftest，抓不到这种失效）。
    现在两种索引都能读：v2 走 postings 还原，v1 直接返回。
    """
    doc_names = bm.get("doc_names")
    postings = bm.get("postings")
    if postings is None:
        return bm.get("_tokens") or {}
    out = {n: [] for n in (doc_names or [])}
    for term, plist in postings.items():
        for item in plist or []:
            try:
                di, freq = int(item[0]), int(item[1])
            except (TypeError, ValueError, IndexError):
                continue
            if 0 <= di < len(doc_names):
                out[doc_names[di]].extend([term] * max(1, freq))
    return out


def cosine_sim(a_tokens, b_tokens):
    """基于加权 token 频次的余弦相似度。"""
    if not a_tokens or not b_tokens:
        return 0.0
    ca, cb = defaultdict(int), defaultdict(int)
    for t in a_tokens:
        ca[t] += 1
    for t in b_tokens:
        cb[t] += 1
    common = set(ca) & set(cb)
    if not common:
        return 0.0
    dot = sum(ca[t] * cb[t] for t in common)
    na = math.sqrt(sum(v * v for v in ca.values()))
    nb = math.sqrt(sum(v * v for v in cb.values()))
    return dot / (na * nb) if na and nb else 0.0


def suggest_links(pages, bm_tokens, targets, topn=5):
    """
    为每个目标页面推荐最该链接到它的候选页面。
    评分 = 内容相似度，且排除已有链接与同源页面。
    """
    suggestions = {}
    for tgt in targets:
        tgt_tokens = bm_tokens.get(tgt, [])
        scored = []
        for other, toks in bm_tokens.items():
            if other == tgt:
                continue
            sim = cosine_sim(tgt_tokens, toks)
            if sim > 0.02:
                scored.append((other, sim))
        scored.sort(key=lambda kv: -kv[1])
        suggestions[tgt] = scored[:topn]
    return suggestions


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    `norm_target` 是本工具的核心归一器——本库已知陷阱里「wikilink 目标要去掉
    目录前缀与 |别名 后缀」全靠它，故夹具必须覆盖全部已知写法变体。
    """
    ok = True
    # ---- norm_target 正例：目录前缀 / 别名 / 锚点 / 表格转义 / 反斜杠 ----
    cases = [
        ("concepts/深度学习", "深度学习", "去目录前缀"),
        ("concepts/深度学习|显示文本", "深度学习", "去别名后缀"),
        ("sources/X#小节", "X", "去锚点"),
        ("raw/clippings/a.md", "a.md", "资源路径取末段（raw 须保留 .md）"),
        ("sources/Foo.md", "Foo", "页面链接须剥 .md（回归：2026-10-10 漏计 523 条）"),
        ("concepts/Bar.md|别名", "Bar", "页面链接带 .md + 别名"),
        ("Foo.md", "Foo", "裸页面链接带 .md（无目录前缀）"),
        ("concepts/X\\|别名", "X", "表格内转义管道"),
        ("  固态电解质  ", "固态电解质", "两端空白"),
        # ⚠️ 记录实测行为：norm_target 会**删掉全部反斜杠**（`.replace("\\","")`），
        #    故 `[[sources/Y\]]` 这种残缺写法会得到 `Y]]`——它**不**负责剥 `[[ ]]`，
        #    也不负责修复已知陷阱第 5 类（尾部带 `\`）。此处如实钉住该行为，
        #    以免日后有人误以为这里做了链接语法修复。
        ("[[sources/Y\\]]", "Y]]", "只归一、不剥 [[ ]] 也不修尾部反斜杠（如实记录）"),
    ]
    for src, want, label in cases:
        got = norm_target(src)
        mark = "ok" if got == want else "FAIL"
        print(f"  [{mark}] norm_target {label}: {src!r} -> {got!r}")
        ok = ok and got == want

    # ---- build_graph 正例/反例 ----
    pages = {
        "A": {"out": ["concepts/B", "sources/不存在", "A"]},
        "B": {"out": ["A"]},
    }
    inbound, outbound = build_graph(pages)
    good = (inbound.get("B") == {"A"}          # 真实目标计入
            and "不存在" not in inbound         # 反例：不存在的目标不得计入
            and inbound.get("A") == {"B"}       # B -> A 计入
            and "A" not in inbound.get("A", set()))   # 反例：自环不得计入
    print(f"  [{'ok' if good else 'FAIL'}] build_graph 只计真实存在、排除自环与断链")
    ok = ok and good

    # ---- cosine_sim 正例/反例 ----
    s = cosine_sim(["a", "b"], ["a", "b"])
    good = abs(s - 1.0) < 1e-9
    print(f"  [{'ok' if good else 'FAIL'}] cosine_sim 同一 token 集 -> {s:.4f} (期望 1.0)")
    ok = ok and good
    s = cosine_sim(["a"], ["b"])
    good = s == 0.0
    print(f"  [{'ok' if good else 'FAIL'}] 反例 无交集 -> {s}")
    ok = ok and good
    s = cosine_sim([], ["b"])
    good = s == 0.0
    print(f"  [{'ok' if good else 'FAIL'}] 反例 空 token -> {s}")
    ok = ok and good

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--suggest", action="store_true", help="生成补链建议")
    ap.add_argument("--type", default="", help="限定页面类型")
    ap.add_argument("--page", default="", help="查询单个页面的链接情况")
    ap.add_argument("--top", type=int, default=30, help="列出前 N 个孤立页面")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    pages = load_full()
    with open(K.BM25_PATH, "r", encoding="utf-8") as f:
        bm = json.load(f)
    bm_tokens = tokens_from_bm(bm)

    inbound, outbound = build_graph(pages)

    if args.page:
        n = args.page
        if n not in pages:
            print(f"未找到页面: {n}")
            return 1
        ins = sorted(inbound.get(n, []))
        outs = sorted(outbound.get(n, []))
        print(f"# {n}  [{pages[n].get('type')}]")
        print(f"\n入站链接 ({len(ins)}):")
        for x in ins:
            print(f"  <- {x}")
        print(f"\n出站链接 ({len(outs)}):")
        for x in outs:
            print(f"  -> {x}")
        return 0

    # 定义"孤立"：入站链接数低于阈值
    all_names = list(pages)
    stats = {n: len(inbound.get(n, set())) for n in all_names}
    orphans = [n for n in all_names if stats[n] == 0]
    weak = [n for n in all_names if 0 < stats[n] <= 1]

    type_filter = [t.strip() for t in args.type.split(",") if t.strip()]
    if type_filter:
        orphans = [n for n in orphans if pages[n].get("type") in type_filter]

    if args.suggest:
        targets = sorted(orphans, key=lambda n: -len(bm_tokens.get(n, [])))[:args.top]
        sugg = suggest_links(pages, bm_tokens, targets)
        if args.json:
            print(json.dumps(sugg, ensure_ascii=False, indent=1))
            return 0
        print(f"# 补链建议（{len(targets)} 个孤立页面的最相关来源）\n")
        for tgt in targets:
            t = pages[tgt].get("type")
            print(f"## {tgt}  [{t}]")
            s = pages[tgt].get("summary", "")[:80]
            if s:
                print(f"   {s}")
            if not sugg[tgt]:
                print("   （无足够相似页面）")
            for other, sim in sugg[tgt]:
                ot = pages[other].get("type")
                print(f"   -> [[{other}]]  [{ot}]  相似度 {sim:.3f}")
            print()
        return 0

    # 概览
    total_links = sum(len(v) for v in outbound.values())
    print(f"页面总数     : {len(all_names)}")
    print(f"链接边总数   : {total_links}")
    print(f"平均入站链接 : {sum(stats.values())/max(1,len(stats)):.2f}")
    print(f"孤立页面     : {len(orphans)}  ({100*len(orphans)/max(1,len(all_names)):.0f}%)")
    print(f"弱连接(<=1)  : {len(weak)}")
    print()
    print(f"=== 入站链接最少的 {args.top} 个页面 ===")
    ranked = sorted(all_names, key=lambda n: (stats[n], -len(bm_tokens.get(n, []))))
    for n in ranked[:args.top]:
        print(f"  [{stats[n]}] {n}  ({pages[n].get('type')})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
